function ev(x,s){if(x.type==='VARIABLE_ALIAS')return s[x.value.id];if(x.type!=='EXPRESSION')return x.value;const a=x.value.expressionArguments.map(v=>ev(v,s));switch(x.value.expressionFunction){case'EQUALS':return a[0]===a[1];case'NOT_EQUAL':return a[0]!==a[1];case'AND':return a.every(Boolean);case'OR':return a.some(Boolean);case'NOT':return !a[0];case'LESS_THAN_OR_EQUAL':return a[0]<=a[1];default:throw Error(x.value.expressionFunction);}}
function run(k,s){function apply(as){for(const a of as){if(a.type==='SET_VARIABLE')s[a.variableId]=ev(a.variableValue,s);else if(a.type==='CONDITIONAL'){for(const b of a.conditionalBlocks)if(!b.condition||ev(b.condition,s)){apply(b.actions);break;}}else if(a.type==='NODE')s.__navigation=a.destinationId;else throw Error(a.type);}}apply(actions[k]);}

